    TK_AUTO,
    TK_BREAK,
    TK_CASE,
    TK_CHAR_KW,        /* char      (distinct from TK_CHAR literal) */
    TK_CONST,
    TK_CONTINUE,
    TK_DEFAULT,
    TK_DO,
    TK_DOUBLE,
    TK_ELSE,
    TK_ENUM,
    TK_EXTERN,
    TK_FLOAT_KW,       /* float     */
    TK_FOR,
    TK_GOTO,
    TK_IF,
    TK_INLINE,
    TK_INT_KW,         /* int       */
    TK_LONG,
    TK_REGISTER,
    TK_RESTRICT,
    TK_RETURN,
    TK_SHORT,
    TK_SIGNED,
    TK_SIZEOF,
    TK_STATIC,
    TK_STRUCT,
    TK_SWITCH,
    TK_TYPEDEF,
