#include "../include/types.h"
#include "../include/codegen.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Minimal FreeLang to C transpiler - Phase 1: Type mapping only */

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <input.fl> [-o output.c]\n", argv[0]);
        return 1;
    }

    const char *input_file = argv[1];
    const char *output_file = "output.c";

    /* Parse output file option */
    for (int i = 2; i < argc - 1; i++) {
        if (strcmp(argv[i], "-o") == 0) {
            output_file = argv[i + 1];
        }
    }

    /* For Phase 1, we just generate a template C program */
    FILE *out = fopen(output_file, "w");
    if (!out) {
        perror("Cannot open output file");
        return 1;
    }

    Codegen *cg = codegen_new(out);

    /* Emit preamble */
    codegen_emit_preamble(cg);

    /* Generate a simple main function */
    FlType *ret_ty = fl_type_void();

    codegen_func_decl(cg, "main", ret_ty, NULL, NULL, 0);
    codegen_func_begin(cg);

    codegen_emit(cg, "printf(\"Hello from Phase 1!\\n\");\n");
    codegen_return(cg, "0");

    codegen_func_end(cg);

    codegen_emit_end(cg);

    codegen_free(cg);
    fl_type_free(ret_ty);
    fclose(out);

    printf("Generated %s from %s\n", output_file, input_file);
    return 0;
}

