#include "../include/types.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

/* Simple test framework */
static int test_count = 0;
static int test_pass = 0;
static int test_fail = 0;

#define TEST(name) \
    void test_##name(void); \
    test_count++; \
    printf("  %s ... ", #name); \
    test_##name(); \
    printf("OK\n"); \
    test_pass++

#define TEST_ASSERT(cond, msg) \
    if (!(cond)) { \
        printf("FAIL: %s\n", msg); \
        test_fail++; \
        exit(1); \
    }

#define TEST_STR_EQ(a, b) \
    TEST_ASSERT(strcmp(a, b) == 0, "string mismatch")

#define TEST_INT_EQ(a, b) \
    TEST_ASSERT((a) == (b), "int mismatch")

/* ===== Tests ===== */

void test_void(void) {
    FlType *ty = fl_type_void();
    TEST_STR_EQ(fl_type_to_c_string(ty), "void");
    TEST_INT_EQ(fl_type_size(ty), 0);
    fl_type_free(ty);
}

void test_bool(void) {
    FlType *ty = fl_type_bool();
    TEST_STR_EQ(fl_type_to_c_string(ty), "int");
    TEST_INT_EQ(fl_type_size(ty), 4);
    fl_type_free(ty);
}

void test_i32(void) {
    FlType *ty = fl_type_i32();
    TEST_STR_EQ(fl_type_to_c_string(ty), "int");
    TEST_INT_EQ(fl_type_size(ty), 4);
    fl_type_free(ty);
}

void test_i64(void) {
    FlType *ty = fl_type_i64();
    TEST_STR_EQ(fl_type_to_c_string(ty), "long");
    TEST_INT_EQ(fl_type_size(ty), 8);
    fl_type_free(ty);
}

void test_f32(void) {
    FlType *ty = fl_type_f32();
    TEST_STR_EQ(fl_type_to_c_string(ty), "float");
    TEST_INT_EQ(fl_type_size(ty), 4);
    fl_type_free(ty);
}

void test_f64(void) {
    FlType *ty = fl_type_f64();
    TEST_STR_EQ(fl_type_to_c_string(ty), "double");
    TEST_INT_EQ(fl_type_size(ty), 8);
    fl_type_free(ty);
}

void test_string(void) {
    FlType *ty = fl_type_string();
    TEST_STR_EQ(fl_type_to_c_string(ty), "char*");
    TEST_INT_EQ(fl_type_size(ty), 8);
    fl_type_free(ty);
}

void test_pointer_to_i32(void) {
    FlType *base = fl_type_i32();
    FlType *ptr = fl_type_pointer(base);
    TEST_STR_EQ(fl_type_to_c_string(ptr), "int*");
    TEST_INT_EQ(fl_type_size(ptr), 8);
    fl_type_free(ptr);
}

void test_pointer_to_f64(void) {
    FlType *base = fl_type_f64();
    FlType *ptr = fl_type_pointer(base);
    TEST_STR_EQ(fl_type_to_c_string(ptr), "double*");
    fl_type_free(ptr);
}

void test_array_of_i32(void) {
    FlType *elem = fl_type_i32();
    FlType *arr = fl_type_array(elem, 10);
    TEST_STR_EQ(fl_type_to_c_string(arr), "int[10]");
    TEST_INT_EQ(fl_type_size(arr), 40);  /* 4 * 10 */
    fl_type_free(arr);
}

void test_array_unsized(void) {
    FlType *elem = fl_type_i32();
    FlType *arr = fl_type_array(elem, -1);
    TEST_STR_EQ(fl_type_to_c_string(arr), "int[]");
    fl_type_free(arr);
}

void test_array_of_f64(void) {
    FlType *elem = fl_type_f64();
    FlType *arr = fl_type_array(elem, 5);
    TEST_STR_EQ(fl_type_to_c_string(arr), "double[5]");
    TEST_INT_EQ(fl_type_size(arr), 40);  /* 8 * 5 */
    fl_type_free(arr);
}

void test_pointer_to_array(void) {
    FlType *arr = fl_type_array(fl_type_i32(), 10);
    FlType *ptr = fl_type_pointer(arr);
    TEST_STR_EQ(fl_type_to_c_string(ptr), "int[10]*");
    fl_type_free(ptr);
}

void test_array_of_pointers(void) {
    FlType *ptr = fl_type_pointer(fl_type_i32());
    FlType *arr = fl_type_array(ptr, 5);
    TEST_STR_EQ(fl_type_to_c_string(arr), "int*[5]");
    fl_type_free(arr);
}

void test_struct(void) {
    FlType *ty = fl_type_struct("Point");
    TEST_STR_EQ(fl_type_to_c_string(ty), "Point");
    fl_type_free(ty);
}

void test_type_equality(void) {
    FlType *a = fl_type_i32();
    FlType *b = fl_type_i32();
    FlType *c = fl_type_i64();

    TEST_ASSERT(fl_type_equals(a, b), "equal i32s should be equal");
    TEST_ASSERT(!fl_type_equals(a, c), "i32 should not equal i64");

    fl_type_free(a);
    fl_type_free(b);
    fl_type_free(c);
}

void test_pointer_equality(void) {
    FlType *a = fl_type_pointer(fl_type_i32());
    FlType *b = fl_type_pointer(fl_type_i32());
    FlType *c = fl_type_pointer(fl_type_i64());

    TEST_ASSERT(fl_type_equals(a, b), "equal pointers should be equal");
    TEST_ASSERT(!fl_type_equals(a, c), "pointer to i32 != pointer to i64");

    fl_type_free(a);
    fl_type_free(b);
    fl_type_free(c);
}

/* ===== Main test runner ===== */

int main(void) {
    printf("Running type system tests...\n");

    /* Scalar types */
    TEST(void);
    TEST(bool);
    TEST(i32);
    TEST(i64);
    TEST(f32);
    TEST(f64);
    TEST(string);

    /* Pointers */
    TEST(pointer_to_i32);
    TEST(pointer_to_f64);

    /* Arrays */
    TEST(array_of_i32);
    TEST(array_unsized);
    TEST(array_of_f64);
    TEST(pointer_to_array);
    TEST(array_of_pointers);

    /* Structs */
    TEST(struct);

    /* Equality */
    TEST(type_equality);
    TEST(pointer_equality);

    printf("\n✓ All %d tests passed!\n", test_pass);
    return 0;
}

