    TEST(pointer_to_f64);

    /* Arrays */
    TEST(array_of_i32);
    TEST(array_unsized);
    TEST(array_of_f64);
    TEST(pointer_to_array);
    TEST(array_of_pointers);

    /* Structs */
    TEST(struct);

    /* Equality */
    TEST(type_equality);
    TEST(pointer_equality);

    printf("\n✓ All %d tests passed!\n", test_pass);
