}

Stmt *stmt_while(Expr *cond, Stmt *body) {
    Stmt *s = calloc(1, sizeof(Stmt));
    s->kind = STMT_WHILE;
    s->while_stmt.condition = cond;
    s->while_stmt.body = body;
    return s;
}

Stmt *stmt_for(const char *var, Expr *start, Expr *end, Stmt *body) {
    Stmt *s = calloc(1, sizeof(Stmt));
    s->kind = STMT_FOR;
    s->for_stmt.var_name = strdup(var);
    s->for_stmt.start = start;
    s->for_stmt.end = end;
