    s->expr = expr;
    return s;
}

/* ---- Function Definition ---- */

FuncDef *func_def_new(const char *name,
                      const char **param_names,
                      FlType **param_types,
                      int param_count,
                      FlType *return_type,
                      Stmt *body) {
