#include "../include/types.h"
#include "../include/ast.h"
#include "../include/codegen.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

/* Test framework */
static int test_count = 0;
static int test_pass = 0;

#define TEST(name) \
    void test_##name(void); \
    test_count++; \
    printf("  %s ... ", #name); \
    fflush(stdout); \
    test_##name(); \
    printf("OK\n"); \
    test_pass++

#define TEST_ASSERT(cond, msg) \
    if (!(cond)) { \
        printf("FAIL: %s\n", msg); \
        exit(1); \
    }

#define GEN_EXPR(expr) \
    ({ \
        FILE *f = fopen("/tmp/test_expr.c", "w"); \
        Codegen *cg = codegen_new(f); \
        char *result = codegen_expression(cg, expr); \
        fclose(f); \
        codegen_free(cg); \
        result; \
    })

/* ===== Tests ===== */

void test_literal_int(void) {
    Expr *e = expr_literal_int(42);
    char *c = GEN_EXPR(e);
    TEST_ASSERT(strstr(c, "42") != NULL, "should contain 42");
    expr_free(e);
}

void test_literal_float(void) {
    Expr *e = expr_literal_float(3.14);
    char *c = GEN_EXPR(e);
    TEST_ASSERT(strstr(c, "3.14") != NULL, "should contain 3.14");
    expr_free(e);
}

void test_literal_string(void) {
    Expr *e = expr_literal_string("hello");
    char *c = GEN_EXPR(e);
    TEST_ASSERT(strstr(c, "hello") != NULL, "should contain hello");
    expr_free(e);
}

void test_var_ref(void) {
    Expr *e = expr_var("myvar");
    char *c = GEN_EXPR(e);
    TEST_ASSERT(strcmp(c, "myvar") == 0, "should be myvar");
    expr_free(e);
}

void test_binary_add(void) {
    Expr *left = expr_literal_int(10);
    Expr *right = expr_literal_int(20);
    Expr *e = expr_binary(left, right, "+");
    char *c = GEN_EXPR(e);
    TEST_ASSERT(strstr(c, "10") != NULL && strstr(c, "+") != NULL && strstr(c, "20") != NULL,
                "should have 10 + 20");
    expr_free(e);
}

void test_binary_mul(void) {
    Expr *left = expr_var("x");
    Expr *right = expr_literal_int(5);
    Expr *e = expr_binary(left, right, "*");
    char *c = GEN_EXPR(e);
    TEST_ASSERT(strstr(c, "x") != NULL && strstr(c, "*") != NULL && strstr(c, "5") != NULL,
                "should have x * 5");
    expr_free(e);
}

void test_unary_neg(void) {
    Expr *op = expr_literal_int(42);
    Expr *e = expr_unary(op, "-");
    char *c = GEN_EXPR(e);
    TEST_ASSERT(strstr(c, "-") != NULL && strstr(c, "42") != NULL,
                "should have -42");
    expr_free(e);
}

void test_unary_not(void) {
    Expr *op = expr_var("flag");
    Expr *e = expr_unary(op, "!");
    char *c = GEN_EXPR(e);
    TEST_ASSERT(strstr(c, "!") != NULL && strstr(c, "flag") != NULL,
                "should have !flag");
    expr_free(e);
}

void test_function_call_no_args(void) {
    Expr *e = expr_call("malloc", NULL, 0);
    char *c = GEN_EXPR(e);
    TEST_ASSERT(strstr(c, "malloc") != NULL && strstr(c, "()") != NULL,
                "should have malloc()");
    expr_free(e);
}

void test_function_call_one_arg(void) {
    Expr *arg1 = expr_literal_int(100);
    Expr *args[] = { arg1 };
    Expr *e = expr_call("square", args, 1);
    char *c = GEN_EXPR(e);
    TEST_ASSERT(strstr(c, "square") != NULL && strstr(c, "100") != NULL,
                "should have square(100)");
    expr_free(e);
}

void test_function_call_two_args(void) {
    Expr *arg1 = expr_var("a");
    Expr *arg2 = expr_var("b");
    Expr *args[] = { arg1, arg2 };
    Expr *e = expr_call("add", args, 2);
    char *c = GEN_EXPR(e);
    TEST_ASSERT(strstr(c, "add") != NULL && strstr(c, "a") != NULL && strstr(c, "b") != NULL,
                "should have add(a, b)");
    expr_free(e);
}

void test_array_index(void) {
    Expr *array = expr_var("arr");
    Expr *index = expr_literal_int(5);
    Expr *e = expr_index(array, index);
    char *c = GEN_EXPR(e);
    TEST_ASSERT(strstr(c, "arr") != NULL && strstr(c, "[") != NULL && strstr(c, "5") != NULL,
                "should have arr[5]");
    expr_free(e);
}

void test_member_access(void) {
    Expr *obj = expr_var("point");
    Expr *e = expr_member(obj, "x");
    char *c = GEN_EXPR(e);
    TEST_ASSERT(strstr(c, "point") != NULL && strstr(c, ".") != NULL && strstr(c, "x") != NULL,
                "should have point.x");
    expr_free(e);
}

void test_complex_expr(void) {
    // (x + 5) * y
    Expr *x = expr_var("x");
    Expr *five = expr_literal_int(5);
    Expr *add = expr_binary(x, five, "+");
    Expr *y = expr_var("y");
    Expr *mul = expr_binary(add, y, "*");

    char *c = GEN_EXPR(mul);
    TEST_ASSERT(strstr(c, "x") != NULL && strstr(c, "5") != NULL &&
                strstr(c, "+") != NULL && strstr(c, "y") != NULL &&
                strstr(c, "*") != NULL,
                "should have (x + 5) * y");
    expr_free(mul);
}

void test_nested_calls(void) {
    // printf(add(1, 2))
    Expr *arg1 = expr_literal_int(1);
    Expr *arg2 = expr_literal_int(2);
    Expr *args1[] = { arg1, arg2 };
    Expr *add_call = expr_call("add", args1, 2);

    Expr *args2[] = { add_call };
    Expr *printf_call = expr_call("printf", args2, 1);

    char *c = GEN_EXPR(printf_call);
    TEST_ASSERT(strstr(c, "printf") != NULL && strstr(c, "add") != NULL,
                "should have printf(add(...))");
    expr_free(printf_call);
}

void test_var_decl_stmt(void) {
    Expr *init = expr_literal_int(42);
    Stmt *s = stmt_var_decl("x", fl_type_i32(), init);

    FILE *f = fopen("/tmp/test_stmt.c", "w");
    Codegen *cg = codegen_new(f);
    codegen_statement(cg, s);
    fclose(f);
    codegen_free(cg);

    // Verify file was created
    FILE *check = fopen("/tmp/test_stmt.c", "r");
    TEST_ASSERT(check != NULL, "output file should exist");
    fclose(check);

    stmt_free(s);
}

void test_return_stmt(void) {
    Expr *val = expr_literal_int(99);
    Stmt *s = stmt_return(val);

    FILE *f = fopen("/tmp/test_stmt.c", "w");
    Codegen *cg = codegen_new(f);
    codegen_statement(cg, s);
    fclose(f);
    codegen_free(cg);

    FILE *check = fopen("/tmp/test_stmt.c", "r");
    TEST_ASSERT(check != NULL, "output file should exist");
    fclose(check);

    stmt_free(s);
}

void test_if_stmt(void) {
    Expr *cond = expr_var("flag");
    Expr *init = expr_literal_int(1);
    Stmt *body = stmt_var_decl("x", fl_type_i32(), init);
    Stmt *s = stmt_if(cond, body, NULL);

    FILE *f = fopen("/tmp/test_stmt.c", "w");
    Codegen *cg = codegen_new(f);
    codegen_statement(cg, s);
    fclose(f);
    codegen_free(cg);

    FILE *check = fopen("/tmp/test_stmt.c", "r");
    TEST_ASSERT(check != NULL, "output file should exist");
    fclose(check);

    stmt_free(s);
}

void test_while_stmt(void) {
    Expr *cond = expr_binary(expr_var("i"), expr_literal_int(10), "<");
    Expr *init = expr_literal_int(0);
    Stmt *body = stmt_var_decl("x", fl_type_i32(), init);
    Stmt *s = stmt_while(cond, body);

    FILE *f = fopen("/tmp/test_stmt.c", "w");
    Codegen *cg = codegen_new(f);
    codegen_statement(cg, s);
    fclose(f);
    codegen_free(cg);

    FILE *check = fopen("/tmp/test_stmt.c", "r");
    TEST_ASSERT(check != NULL, "output file should exist");
    fclose(check);

    stmt_free(s);
}

void test_for_stmt(void) {
    Expr *start = expr_literal_int(1);
    Expr *end = expr_literal_int(10);
    Expr *init = expr_literal_int(0);
    Stmt *body = stmt_var_decl("sum", fl_type_i32(), init);
    Stmt *s = stmt_for("i", start, end, body);

    FILE *f = fopen("/tmp/test_stmt.c", "w");
    Codegen *cg = codegen_new(f);
    codegen_statement(cg, s);
    fclose(f);
    codegen_free(cg);

    FILE *check = fopen("/tmp/test_stmt.c", "r");
    TEST_ASSERT(check != NULL, "output file should exist");
    fclose(check);

    stmt_free(s);
}

/* ===== Main test runner ===== */

int main(void) {
    printf("Running expression and statement tests (Phase 2)...\n");

    /* Literals */
    TEST(literal_int);
    TEST(literal_float);
    TEST(literal_string);

    /* Variables */
    TEST(var_ref);

    /* Binary operations */
    TEST(binary_add);
    TEST(binary_mul);

    /* Unary operations */
    TEST(unary_neg);
    TEST(unary_not);

    /* Function calls */
    TEST(function_call_no_args);
    TEST(function_call_one_arg);
    TEST(function_call_two_args);

    /* Array & member access */
    TEST(array_index);
    TEST(member_access);

    /* Complex expressions */
    TEST(complex_expr);
    TEST(nested_calls);

    /* Statements */
    TEST(var_decl_stmt);
    TEST(return_stmt);
    TEST(if_stmt);
    TEST(while_stmt);
    TEST(for_stmt);

    printf("\n✓ All %d Phase 2 tests passed!\n", test_pass);
    return 0;
}

