#include "../include/codegen.h"
#include "../include/types.h"
#include "../include/ast.h"
#include <stdlib.h>
#include <stdarg.h>
#include <string.h>
#include <stdio.h>

Codegen *codegen_new(FILE *out) {
    Codegen *cg = malloc(sizeof(Codegen));
    cg->out = out;
    cg->indent_level = 0;
    cg->indent_str = "  ";
    cg->expr_depth = 0;
    return cg;
}

void codegen_free(Codegen *cg) {
    if (cg) free(cg);
}

static void emit_indent(Codegen *cg) {
    for (int i = 0; i < cg->indent_level; i++) {
        fputs(cg->indent_str, cg->out);
    }
}

void codegen_emit(Codegen *cg, const char *fmt, ...) {
    emit_indent(cg);

    va_list ap;
    va_start(ap, fmt);
    vfprintf(cg->out, fmt, ap);
    va_end(ap);
}

void codegen_newline(Codegen *cg) {
    fputc('\n', cg->out);
}

void codegen_indent(Codegen *cg) {
    cg->indent_level++;
}

void codegen_unindent(Codegen *cg) {
    if (cg->indent_level > 0) cg->indent_level--;
}

/* Generate expression as string */
char *codegen_expression(Codegen *cg, Expr *expr) {
    static char buf[2048];  /* static for now; TODO: use string builder */

    if (!expr) return "";

    switch (expr->kind) {
        case EXPR_LITERAL:
            if (expr->type->kind == FL_TYPE_I32 || expr->type->kind == FL_TYPE_I64) {
                snprintf(buf, sizeof(buf), "%lld", expr->lit_int.ival);
            } else if (expr->type->kind == FL_TYPE_F32 || expr->type->kind == FL_TYPE_F64) {
                snprintf(buf, sizeof(buf), "%.6f", expr->lit_float.fval);
            } else if (expr->type->kind == FL_TYPE_STRING) {
                snprintf(buf, sizeof(buf), "\"%s\"", expr->lit_string.sval);
            }
            return buf;

        case EXPR_VAR:
            snprintf(buf, sizeof(buf), "%s", expr->var.name);
            return buf;

        case EXPR_BINARY: {
            char *left = codegen_expression(cg, expr->binary.left);
            char *right = codegen_expression(cg, expr->binary.right);
            snprintf(buf, sizeof(buf), "(%s %s %s)", left, expr->binary.op, right);
            return buf;
        }

        case EXPR_UNARY: {
            char *operand = codegen_expression(cg, expr->unary.operand);
            snprintf(buf, sizeof(buf), "(%s%s)", expr->unary.op, operand);
            return buf;
        }

        case EXPR_CALL: {
            snprintf(buf, sizeof(buf), "%s(", expr->call.func_name);
            for (int i = 0; i < expr->call.arg_count; i++) {
                if (i > 0) strcat(buf, ", ");
                char *arg = codegen_expression(cg, expr->call.args[i]);
                strcat(buf, arg);
            }
            strcat(buf, ")");
            return buf;
        }

        case EXPR_INDEX: {
            char *array = codegen_expression(cg, expr->index.array);
            char *index = codegen_expression(cg, expr->index.index);
            snprintf(buf, sizeof(buf), "%s[%s]", array, index);
            return buf;
        }

        case EXPR_MEMBER: {
            char *obj = codegen_expression(cg, expr->member.object);
            snprintf(buf, sizeof(buf), "%s.%s", obj, expr->member.field);
            return buf;
        }

        default:
            return "???";
    }
}

/* Generate statement */
void codegen_statement(Codegen *cg, Stmt *stmt) {
    if (!stmt) return;

    switch (stmt->kind) {
        case STMT_VAR_DECL: {
            const char *c_type = fl_type_to_c_string(stmt->var_decl.type);
            codegen_emit(cg, "%s %s", c_type, stmt->var_decl.name);

            if (stmt->var_decl.init) {
                char *init = codegen_expression(cg, stmt->var_decl.init);
                fprintf(cg->out, " = %s", init);
            }

            fputs(";\n", cg->out);
            break;
        }

        case STMT_EXPR: {
            char *expr = codegen_expression(cg, stmt->expr);
            codegen_emit(cg, "%s;\n", expr);
            break;
        }

        case STMT_RETURN: {
            if (stmt->ret.value) {
                char *val = codegen_expression(cg, stmt->ret.value);
                codegen_emit(cg, "return %s;\n", val);
            } else {
                codegen_emit(cg, "return;\n");
            }
            break;
        }

        case STMT_IF: {
            char *cond = codegen_expression(cg, stmt->if_stmt.condition);
            codegen_emit(cg, "if (%s) {\n", cond);
            codegen_indent(cg);
            codegen_statement(cg, stmt->if_stmt.then_body);
            codegen_unindent(cg);

            if (stmt->if_stmt.else_body) {
                codegen_emit(cg, "} else {\n");
                codegen_indent(cg);
                codegen_statement(cg, stmt->if_stmt.else_body);
                codegen_unindent(cg);
                codegen_emit(cg, "}\n");
            } else {
                codegen_emit(cg, "}\n");
            }
            break;
        }

        case STMT_WHILE: {
            char *cond = codegen_expression(cg, stmt->while_stmt.condition);
            codegen_emit(cg, "while (%s) {\n", cond);
            codegen_indent(cg);
            codegen_statement(cg, stmt->while_stmt.body);
            codegen_unindent(cg);
            codegen_emit(cg, "}\n");
            break;
        }

        case STMT_FOR: {
            char *start = codegen_expression(cg, stmt->for_stmt.start);
            char *end = codegen_expression(cg, stmt->for_stmt.end);
            codegen_emit(cg, "for (int %s = %s; %s <= %s; %s++) {\n",
                        stmt->for_stmt.var_name, start,
                        stmt->for_stmt.var_name, end,
                        stmt->for_stmt.var_name);
            codegen_indent(cg);
            codegen_statement(cg, stmt->for_stmt.body);
            codegen_unindent(cg);
            codegen_emit(cg, "}\n");
            break;
        }

        case STMT_BLOCK: {
            for (int i = 0; i < stmt->block.count; i++) {
                codegen_statement(cg, stmt->block.stmts[i]);
            }
            break;
        }

        default:
            codegen_emit(cg, "/* unknown stmt */\n");
    }
}

/* Generate function */
void codegen_function(Codegen *cg, FuncDef *func) {
    const char *ret_str = fl_type_to_c_string(func->return_type);

    codegen_emit(cg, "%s %s(", ret_str, func->name);

    if (func->param_count == 0) {
        fputs("void", cg->out);
    } else {
        for (int i = 0; i < func->param_count; i++) {
            if (i > 0) fputs(", ", cg->out);
            const char *ptype = fl_type_to_c_string(func->param_types[i]);
            fprintf(cg->out, "%s %s", ptype, func->param_names[i]);
        }
    }

    fputs(" {\n", cg->out);
    codegen_indent(cg);
    codegen_statement(cg, func->body);
    codegen_unindent(cg);
    codegen_emit(cg, "}\n\n");
}

/* Generate program */
void codegen_program(Codegen *cg, Program *prog) {
    codegen_emit_preamble(cg);

    for (int i = 0; i < prog->func_count; i++) {
        codegen_function(cg, prog->functions[i]);
    }

    codegen_emit_end(cg);
}

/* Emit includes */
void codegen_emit_preamble(Codegen *cg) {
    fputs("#include <stdio.h>\n", cg->out);
    fputs("#include <stdlib.h>\n", cg->out);
    fputs("#include <string.h>\n", cg->out);
    fputs("\n", cg->out);
}

void codegen_emit_end(Codegen *cg) {
    /* Nothing special needed at end */
}

/* Legacy helper functions */

void codegen_var_decl(Codegen *cg, const char *name, FlType *ty,
                      const char *init_expr) {
    const char *c_type = fl_type_to_c_string(ty);

    if (init_expr) {
        codegen_emit(cg, "%s %s = %s;", c_type, name, init_expr);
    } else {
        codegen_emit(cg, "%s %s;", c_type, name);
    }
    codegen_newline(cg);
}

void codegen_func_decl(Codegen *cg, const char *name, FlType *ret_ty,
                       const char **param_names, FlType **param_types,
                       int param_count) {
    const char *ret_str = fl_type_to_c_string(ret_ty);

    codegen_emit(cg, "%s %s(", ret_str, name);

    if (param_count == 0) {
        fputs("void", cg->out);
    } else {
        for (int i = 0; i < param_count; i++) {
            if (i > 0) fputs(", ", cg->out);
            const char *param_type_str = fl_type_to_c_string(param_types[i]);
            fprintf(cg->out, "%s %s", param_type_str, param_names[i]);
        }
    }

    fputs(")", cg->out);
}

void codegen_func_begin(Codegen *cg) {
    fputs(" {\n", cg->out);
    codegen_indent(cg);
}

void codegen_func_end(Codegen *cg) {
    codegen_unindent(cg);
    codegen_emit(cg, "}\n");
    codegen_newline(cg);
}

void codegen_return(Codegen *cg, const char *expr) {
    if (expr) {
        codegen_emit(cg, "return %s;", expr);
    } else {
        codegen_emit(cg, "return;");
    }
    codegen_newline(cg);
}

